  'bun run build',
  'bun run check',
  'bun run typecheck',
  'bun run typecheck:ci',
  'bun run lint',
  'bun run test:e2e',
  'bun test',
  'bunx tsc --noEmit',
  'bunx playwright test',
  'tsc --noEmit',
  'playwright test',
  'cargo build',
  'cargo check',
  'cargo test',
  'cargo clippy',
  'go build ./...',
  'go test ./...',
  'pytest -q',
  'python -m pytest -q',
  '/usr/bin/env CI=1 bun test',
  'sudo -n cargo test',
  'time bun run typecheck',
  '(bun run typecheck)',
  'b""un test',
  'true & bun run typecheck',
